input.command:
time duckdb match.db -c "
INSTALL spatial; LOAD spatial;
-- buffered dissolved union of listed parcels; deg = 25/111320
CREATE OR REPLACE TABLE uni AS
  SELECT ST_Union_Agg(ST_Buffer(g, 25.0/111320.0)) AS ug FROM parcels;
CREATE OR REPLACE TABLE union_frac AS
  SELECT f.field_id,
         ST_Area(ST_Intersection(f.g, u.ug)) / f.field_area AS union_frac
  FROM fields f, uni u
  WHERE ST_Intersects(f.g, u.ug);
SELECT count(*) FROM union_frac;
"

