INSTALL spatial; LOAD spatial;
-- add spheroid area (ha) to fields
ALTER TABLE matched ADD COLUMN IF NOT EXISTS area_ha DOUBLE;
UPDATE matched SET area_ha = (SELECT ST_Area_Spheroid(f.g)/10000.0 FROM fields f WHERE f.field_id=matched.field_id);
-- verify no null primary among matched
SELECT count(*) FILTER (WHERE primary_cod IS NULL) null_primary FROM matched WHERE by_primary OR by_aggregate;
-- q11
SELECT round(min(max_single_frac),6) min_single, round(avg(max_single_frac),6) avg_single, round(avg(union_frac),6) avg_union
FROM matched WHERE by_primary OR by_aggregate;
-- q14
SELECT round(sum(area_ha),6) matched_field_ha FROM matched WHERE by_primary OR by_aggregate;
"

cd /workspace
