cd /workspace
duckdb match.db <<'SQL'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy=true;
-- flagged cadaster centroids in EPSG:5880
CREATE OR REPLACE TABLE flagged_cent AS
SELECT f.cod_imovel, split_part(f.cod_imovel,'-',2) AS muni_code, d.dominant_mb,
       ST_Transform(ST_Centroid(p.g), 'EPSG:4674','EPSG:5880', true) AS c5880
FROM flagged f JOIN parcels p ON p.cod_imovel=f.cod_imovel
JOIN domclass d ON d.cod_imovel=f.cod_imovel;
-- facilities in 5880 (only delivery tiers)
CREATE OR REPLACE TABLE fac5880 AS
SELECT entity_id, entity_kind, tier, weight, basis,
       ST_Transform(ST_GeomFromWKB(geom_wkb),'EPSG:4326','EPSG:5880', true) AS g5880
FROM 'facilities.parquet'
WHERE tier IN ('intake_point','slaughter_point','mill_point','gravity_catchment');
SELECT count(*) FROM flagged_cent;
SELECT count(*) FROM fac5880;
SQL
